#import <Foundation/Foundation.h>
#import "../App/AI/Core/TFAIContextProjection.h"
#import "../App/AI/Core/TFAITextLoop.h"
static NSUInteger checks=0,scenarios=0,retained=0,reused=0,fieldPages=0;
static void Check(BOOL ok,NSString *msg){checks++;if(!ok){NSLog(@"FAIL %@",msg);exit(1);}}
static NSString *J(id v){return [[NSString alloc]initWithData:[NSJSONSerialization dataWithJSONObject:v options:NSJSONWritingSortedKeys error:nil] encoding:NSUTF8StringEncoding];}
static NSMutableArray *History(NSUInteger size,NSString *suffix){NSMutableString *text=[NSMutableString new];for(NSUInteger i=0;text.length<size;i++)[text appendFormat:@"line %lu 中文 😀 %@\n",(unsigned long)i,suffix];NSDictionary *result=@{@"path":@"Source.xm",@"start_line":@10,@"sha256":suffix,@"content":text};return [@[@{@"role":@"user",@"content":@"Read and modify the selected file"},@{@"role":@"assistant",@"content":@"",@"tool_calls":@[@{@"id":@"source",@"name":@"read_file",@"arguments":@{@"path":@"Source.xm"}}]},@{@"role":@"tool",@"tool_call_id":@"source",@"content":J(result)}] mutableCopy];}
int main(){@autoreleasepool{
 Check(TFAIExplicitRepetitionRequest(@"重复输出这个词 100 次"),@"explicit requested repetition is allowed");
 Check(!TFAIExplicitRepetitionRequest(@"修复重复读取问题"),@"bug report about repetition does not disable guard");
 id previous=[NSUserDefaults.standardUserDefaults objectForKey:@"TFAIContextBudgetKiB"];NSArray *schemas=@[TFAIContextProjection.schema];
 for(NSUInteger budget=64;budget<=1024;budget*=2)for(NSUInteger n=0;n<120;n++){
  scenarios++;[TFAIContextProjection setBudgetKiB:budget];NSMutableArray *history=History(6000+n*70,[NSString stringWithFormat:@"v%lu",(unsigned long)n]);NSDictionary *stats=nil;NSArray *wire=[TFAIContextProjection project:history schemas:schemas statistics:&stats error:nil];Check(wire&&[stats[@"afterTextJSONBytes"] unsignedIntegerValue]<=budget*1024,@"bounded recent source request fits hard budget");
  BOOL exact=NO;for(NSDictionary *m in wire)if([m[@"tool_call_id"] isEqual:@"source"]&&[m[@"content"] isEqual:history.lastObject[@"content"]])exact=YES;if(exact)retained++;
  if(budget>=128)Check(exact,@"reasonable recent source preserved verbatim when allowance fits");
  NSDictionary *page=[TFAIContextProjection read:@{@"ref":@"result:source",@"limit":@512} messages:history visibleMessages:@[history.lastObject] error:nil];Check([page[@"already_visible"] boolValue]&&!page[@"text"]&&page[@"visible_location"],@"original visible tool result reused");reused+=[page[@"already_visible"] boolValue];
  page=[TFAIContextProjection read:@{@"ref":@"result:source",@"field":@"content",@"start_line":@3,@"line_count":@10} messages:history error:nil];Check(page&&[page[@"original_tool"] isEqual:@"read_file"]&&[page[@"start_line"] isEqual:@12]&&[page[@"text"] hasPrefix:@"line 2 "],@"structured source page skips JSON and preserves absolute source line");fieldPages++;
  NSDictionary *again=[TFAIContextProjection read:@{@"ref":@"result:source",@"field":@"content",@"start_line":@3,@"line_count":@10} messages:history visibleMessages:@[@{@"role":@"tool",@"content":J(page)}] error:nil];Check([again[@"already_visible"] boolValue],@"visible field range deduplicated");
  NSDictionary *missing=[TFAIContextProjection read:@{@"ref":@"result:source",@"field":@"content",@"start_line":@3,@"line_count":@10} messages:history visibleMessages:@[] error:nil];Check([missing isEqual:page],@"missing field range can always be recovered");
 }
 for(NSUInteger limit=128;limit<=2048;limit*=2){NSMutableArray *large=History(35000,@"bounded");NSDictionary *p=[TFAIContextProjection read:@{@"ref":@"result:source",@"field":@"content",@"max_chars":@(limit),@"line_count":@400} messages:large error:nil];Check(p&&[p[@"text"] length]<=limit&&p[@"next_line"]!=NSNull.null,@"explicit field text ceiling returns a precise continuation");}
 NSMutableArray *history=History(20000,@"last");NSString *body=[NSJSONSerialization JSONObjectWithData:[history.lastObject[@"content"] dataUsingEncoding:NSUTF8StringEncoding] options:0 error:nil][@"content"];
 for(NSDictionary *bad in @[@{@"field":@"password"},@{@"field":@"content",@"offset":@0},@{@"field":@"content",@"line_count":@401},@{@"field":@"content",@"start_line":@0},@{@"field":@"content",@"start_line":@1.5},@{@"field":@"content",@"column":@-1},@{@"line_count":@5},@{@"field":@"content",@"start_line":@YES},@{@"field":@"content",@"start_line":@1e30},@{@"field":@"content",@"max_chars":@0},@{@"field":@"content",@"max_chars":@16385},@{@"field":@"content",@"max_chars":@YES},@{@"max_chars":@100}]){NSMutableDictionary *args=[bad mutableCopy];args[@"ref"]=@"result:source";Check(![TFAIContextProjection read:args messages:history error:nil],@"invalid semantic selector fails safely");}
 NSMutableArray *longLine=History(10,@"line");NSMutableString *text=[NSMutableString new];for(int n=0;n<25000;n++)[text appendString:@"中😀"];[text appendString:@"\nlast\n"];longLine[2]=@{@"role":@"tool",@"tool_call_id":@"source",@"content":J(@{@"content":text})};NSMutableString *joined=[NSMutableString new];NSDictionary *cursor=@{@"ref":@"result:source",@"field":@"content",@"line_count":@200};for(NSUInteger i=0;i<50;i++){NSDictionary *p=[TFAIContextProjection read:cursor messages:longLine error:nil];Check(p!=nil,@"unicode long line always advances");[joined appendString:p[@"text"]];if(p[@"next_line"]==NSNull.null)break;cursor=@{@"ref":@"result:source",@"field":@"content",@"start_line":p[@"next_line"],@"column":p[@"next_column"],@"line_count":@200};}Check([joined isEqual:text],@"long-line semantic pagination exactly reconstructs unicode source");
 for(NSUInteger n=0;n<500;n++){NSString *sentence=[NSString stringWithFormat:@"我正在检查第 %lu 个目标的已有信息，接下来需要完成实际修改。",(unsigned long)n];NSMutableString *loop=[NSMutableString new];for(int i=0;i<12;i++)[loop appendString:sentence];Check(TFAIRepeatingProse(loop)!=NSNotFound,@"natural language chant detected");Check(TFAIRepeatingProse([@"```objc\n" stringByAppendingString:loop])==NSNotFound,@"code blocks not treated as prose loops");Check(TFAIRepeatingProse([@"| 模块 | 内容 |\n" stringByAppendingString:loop])==NSNotFound,@"tables exempt from prose rule");NSMutableString *varied=[NSMutableString new];for(int i=0;i<12;i++)[varied appendFormat:@"现在检查的是第 %d 个文件，获得不同结果并继续推进任务。",i];Check(TFAIRepeatingProse(varied)==NSNotFound,@"different task progress text remains valid");}
 Check(body.length>0,@"fixture valid");
 if(previous)[NSUserDefaults.standardUserDefaults setObject:previous forKey:@"TFAIContextBudgetKiB"];else[NSUserDefaults.standardUserDefaults removeObjectForKey:@"TFAIContextBudgetKiB"];
 NSDictionary *report=@{@"kind":@"deterministic_projection_and_text_tests",@"checks":@(checks),@"projection_scenarios":@(scenarios),@"recent_originals_retained":@(retained),@"visible_originals_reused":@(reused),@"semantic_pages_verified":@(fieldPages),@"prose_cases":@2000};printf("%s\n",J(report).UTF8String);
}return 0;}
